43	  payout: number;
44	  remainingCap: number;
45	}
46	
47	export interface ScenarioResult {
48	  results: Result[];
49	}
50	
51	const PROCESSING_FEE = 5;
52	const FIRST_INSURANCE_SURCHARGE_RATE = 1 / 10;
53	// Base premium for a single item of each type.
54	const UNIT_BASE_PREMIUMS: Record<string, number> = {
55	  sword: 100,
56	  amulet: 60,
57	  staff: 80,
58	  potion: 40,
59	  rune: 25,
60	  moonstone: 25,
61	};
62	
63	const CURSE_SURCHARGE_RATE = 1 / 2;
64	const HIGH_ENCHANTMENT_THRESHOLD = 5;
65	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 3 / 10;
66	const BLOCK_SIZE = 3;
67	const BLOCK_BASE_PREMIUM = 60;
68	
69	const countByType = (items: Item[]): Map<string, number> =>
70	  items.reduce(
71	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
72	    new Map<string, number>(),
73	  );
74	
75	// A building block of 3 alike components is offered at a special base premium.
76	const basePremiumForItemGroup = (type: string, count: number): number =>
77	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * UNIT_BASE_PREMIUMS[type];
78	
79	const policyBasePremium = (items: Item[]): number =>
80	  [...countByType(items)].reduce(
81	    (total, [type, count]) => total + basePremiumForItemGroup(type, count),
82	    0,
83	  );
84	
85	const isHighlyEnchanted = (item: Item): boolean =>
86	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
87	
88	const surchargeRate = (item: Item): number =>
89	  (item.cursed ? CURSE_SURCHARGE_RATE : 0) +
90	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_RATE : 0);
91	
92	// Item-specific modifiers apply to the base premium of the affected item.
93	const itemSurcharges = (items: Item[]): number =>
94	  items.reduce(
95	    (total, item) => total + UNIT_BASE_PREMIUMS[item.type] * surchargeRate(item),
96	    0,
97	  );
98	
99	// Premiums round up, in the MHPCO's favour. The surcharge is added as a
100	// separate term rather than folded into a `base * 1.1` factor, which is not
101	// exact in binary floating point (100 * 1.1 === 110.00000000000001).
102	const quotePremium = (items: Item[]): number => {
103	  const base = policyBasePremium(items);
104	  return Math.ceil(
105	    base +
106	      itemSurcharges(items) +
107	      base * FIRST_INSURANCE_SURCHARGE_RATE +
108	      PROCESSING_FEE,
109	  );
110	};
111	
112	const quote = (step: QuoteStep): QuoteResult => ({
113	  premium: quotePremium(step.items),
114	});
115	
116	const runStep = (step: Step): Result => {
117	  switch (step.op) {
118	    case "quote":
119	      return quote(step);
120	    default:
121	      throw new Error(`unsupported step: ${step.op}`);
122	  }
123	};
124	
125	export const runScenario = (scenario: Scenario): ScenarioResult => ({
126	  results: scenario.steps.map(runStep),
127	});
